def clear_tip_dispatches(apps, schema_editor):
    # The old rows are one per (person, day); the new ones one per (person,
    # slot). Only kept for two days anyway, so they are dropped, not converted.
    apps.get_model("wellbeing", "TipDispatch").objects.all().delete()


def agenda_for_subscribed(apps, schema_editor):
    # Tips follow the person's workday: everyone with a device gets one with
    # the defaults (08:00-18:00, Monday to Friday, every 60 min).
    ReminderSetting = apps.get_model("wellbeing", "ReminderSetting")
    PushSubscription = apps.get_model("wellbeing", "PushSubscription")
    missing = (
        PushSubscription.objects.filter(membership__reminder_setting__isnull=True)
        .values_list("membership_id", flat=True)
        .distinct()
    )
    ReminderSetting.objects.bulk_create(
        [ReminderSetting(membership_id=pk) for pk in missing]
    )


